#include <iostream>
#include <memory>
#include <stdexcept>
#include <type_traits>
struct MyData { int val; bool operator<=(const MyData& other) const { return val <= other.val; } };
template <class T1, class D1, class T2, class D2>
bool operator<=(const std::unique_ptr<T1, D1>& x, const std::unique_ptr<T2, D2>& y) {
  if (!x && !y) return true;
  if (!x) return true;
  if (!y) return false;
  if constexpr (std::is_same_v<T1,T2>){
    return *x <= *y; 
  } else {
    throw std::runtime_error("Cannot compare unique_ptrs of different incompatible types");
  }
}
int main() {
      auto ptr1 = std::make_unique<MyData>( {5} );
      auto ptr2 = std::make_unique<MyData>( {10} );
      auto ptr3 = std::unique_ptr<MyData>(nullptr);
      try {
          std::cout << (ptr1 <= ptr2) << std::endl; // Output: 1 (true)
          std::cout << (ptr2 <= ptr1) << std::endl; // Output: 0 (false)
          std::cout << (ptr1 <= ptr3) << std::endl; // Output: 0 (false)
          std::cout << (ptr3 <= ptr1) << std::endl; // Output: 1 (true)
          std::cout << (ptr3 <= ptr3) << std::endl; // Output: 1 (true) 
          // Example of incompatible types (will throw exception):
          // std::cout << (ptr1 <= std::make_unique<int>(10)) << std::endl; 
      } catch (const std::runtime_error& error) {
          std::cerr << "Error: " << error.what() << std::endl;
      }
      return 0;
    }
